/*
 * TLS client certificate options for the k6 load tests (mTLS scenarios): when the
 * TLS_CLIENT_CERT and TLS_CLIENT_KEY environment variables point to a client
 * certificate and key (PEM, generated by certs/generate-certs.sh), the requests
 * are sent with mutual TLS.
 */

// open() is a k6 global (available in the init context of the modules too); the
// certificate paths come from the environment, resolved against the main script

/**
 * Build the k6 options fragment for the TLS client certificate, an empty object
 * when no client certificate is configured
 *
 * @param domains the domains the certificate applies to (default localhost:8443,
 *                the TLS port of the bridge HTTPS listener)
 * @return the options fragment ({ tlsAuth: [...] }) or {}
 */
export function tlsClientOptions(domains) {
  const certPath = __ENV.TLS_CLIENT_CERT;
  const keyPath = __ENV.TLS_CLIENT_KEY;
  if (!certPath || !keyPath) {
    return {};
  }
  return {
    tlsAuth: [{
      // the tlsAuth domains do not include the port
      domains: domains || ['localhost'],
      cert: open(certPath),
      key: open(keyPath),
    }],
  };
}
